242	    /// {
243	    ///     "//": "...",
244	    ///     "options": {
245	    ///         "strictCase": false,
246	    ///         "enumMemberCase": "CONSTANT_CASE"
247	    ///     }
248	    /// }
249	    /// ```
250	    ///
251	    /// ### strictCase
252	    ///
253	    /// When this option is set to `true`, it forbids consecutive uppercase characters in [`camelCase`
