64	    /// assert_eq!(Case::identify("V8Engine", /* no effect */ true), Case::Pascal);
65	    ///
66	    /// assert_eq!(Case::identify("http_server", /* no effect */ true), Case::Snake);
67	    ///
68	    /// assert_eq!(Case::identify("HTTPSERVER", /* no effect */ true), Case::Upper);
69	    ///
70	    /// assert_eq!(Case::identify("100", /* no effect */ true), Case::Uni);
71	    /// assert_eq!(Case::identify("안녕하세요", /* no effect */ true), Case::Uni);
72	    ///
73	    /// assert_eq!(Case::identify("", /* no effect */ true), Case::Unknown);
